### 4.2 Spring 트랜잭션 매니저와 통합

```kotlin
// exposed-spring-boot-starter가 자동으로 SpringTransactionManager를 설정
// Spring의 @Transactional과 Exposed의 transaction {} 모두 사용 가능

@Service
class OrderService(
    private val orderRepository: OrderExposedRepository
) {
    // Spring @Transactional 사용
    @Transactional
    fun createOrder(request: CreateOrderRequest): Long {
        return orderRepository.create(request)
    }
}

@Repository
class OrderExposedRepository {
    // Spring 트랜잭션 컨텍스트 내에서 Exposed DSL 사용
    fun create(request: CreateOrderRequest): Long {
        val orderId = Orders.insertAndGetId {
            it[userId] = request.userId
            it[status] = "PENDING"
            it[totalAmount] = request.totalAmount
        }

        OrderItems.batchInsert(request.items) { item ->
            this[OrderItems.orderId] = orderId
            this[OrderItems.productId] = item.productId
            this[OrderItems.quantity] = item.quantity
            this[OrderItems.unitPrice] = item.unitPrice
        }

        return orderId.value
    }
}
```

